from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG_INF = -10**30

        def make_node(v: int):
            return [v, v, v, v]  # sum, max_prefix, max_suffix, max_subarray

        EMPTY = [0, NEG_INF, NEG_INF, NEG_INF]

        def merge(a, b):
            return [
                a[0] + b[0],
                max(a[1], a[0] + b[1]),
                max(b[2], b[0] + a[2]),
                max(a[3], b[3], a[2] + b[1]),
            ]

        size = 1
        while size < n:
            size *= 2

        seg = [EMPTY[:] for _ in range(2 * size)]
        for i, v in enumerate(nums):
            seg[size + i] = make_node(v)

        for i in range(size - 1, 0, -1):
            seg[i] = merge(seg[2 * i], seg[2 * i + 1])

        def update(pos: int, node):
            idx = size + pos
            seg[idx] = node[:]
            idx //= 2
            while idx:
                seg[idx] = merge(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        ans = seg[1][3]

        positions = defaultdict(list)
        for i, v in enumerate(nums):
            if v < 0:
                positions[v].append(i)

        for v, inds in positions.items():
            if len(inds) == n:
                continue

            for i in inds:
                update(i, EMPTY)

            ans = max(ans, seg[1][3])

            for i in inds:
                update(i, make_node(v))

        return ans
